 Reply awaitReply(Rpc reply,int seconds)throws Exception{long started=System.currentTimeMillis();for(;;){try{return reply.done.get(1,TimeUnit.SECONDS);}catch(TimeoutException waiting){if(!online)throw new IOException("Pika disconnected");if(!deviceBusy&&--seconds<=0)throw waiting;if(System.currentTimeMillis()-started>600000)throw waiting;}}}
 static byte muLaw(int sample){int sign=(sample>>8)&128;if(sign!=0)sample=-sample;sample=Math.min(sample,32635)+132;int exponent=7;for(int mask=16384;(sample&mask)==0&&exponent>0;mask>>=1)exponent--;return (byte)~(sign|(exponent<<4)|((sample>>(exponent+3))&15));}
 void openSpeech(int id,JSONObject message){SpeechFlow flow=fastSpeech&&message.has("stream")?new SpeechFlow(message.optLong("stream")):null;if(flow!=null)speechFlows.put(id,flow);CompletableFuture<Void> done=new CompletableFuture<>();streamDone.put(id,done);BluetoothGatt session=gatt;network.execute(()->{javax.net.ssl.HttpsURLConnection c=null;try{c=(javax.net.ssl.HttpsURLConnection)new java.net.URL("https://api.openai.com/v1/audio/speech").openConnection();speech.put(id,c);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+message.getString("key"));c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);byte[] body=message.getJSONObject("request").toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(body.length);try(OutputStream out=c.getOutputStream()){out.write(body);}if(c.getResponseCode()!=200)throw new IOException("Speech provider rejected request");send(3,id,new byte[0]).get(15,TimeUnit.SECONDS);try(InputStream in=new BufferedInputStream(c.getInputStream())){byte[] block=new byte[8000];int count=0,low;while((low=in.read())>=0){int high=in.read();if(high<0)throw new IOException("Incomplete PCM sample");block[count++]=muLaw((short)(low|(high<<8)));if(count==block.length){sendVoiceBlock(id,flow,block.clone());count=0;}}if(count>0)sendVoiceBlock(id,flow,Arrays.copyOf(block,count));}if(speech.get(id)==c)send(5,id,new byte[0]);}catch(Exception e){if(gatt!=null&&speech.get(id)==c)send(6,id,new byte[0]);}finally{speech.remove(id);if(flow!=null){speechFlows.remove(id,flow);flow.close();}if(c!=null)c.disconnect();done.complete(null);streamDone.remove(id,done);}});}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
